<template>
  <div class="self-center flex flex-col gap-6 flex-auto w-full justify-center">
    <form class="grid grid-cols-2 gap-4" @submit="onSubmit">
      <FormItemWrapper name="first_name" label="First Name" item-class="col-span-2 md:col-span-1">
        <template #default="{ slots }">
          <Input
            id="first_name"
            type="text"
            placeholder="John"
            v-bind="slots.componentField"
            :disabled="isReferingContact"
          />
        </template>
      </FormItemWrapper>
      <FormItemWrapper name="last_name" label="Last Name" item-class="col-span-2 md:col-span-1">
        <template #default="{ slots }">
          <Input
            id="last_name"
            type="text"
            placeholder="Doe"
            v-bind="slots.componentField"
            :disabled="isReferingContact"
          />
        </template>
      </FormItemWrapper>
      <FormItemWrapper name="email" label="Email" item-class="col-span-2">
        <template #default="{ slots }">
          <Input
            id="email"
            type="text"
            placeholder="referral@example.com"
            v-bind="slots.componentField"
            :disabled="isReferingContact"
          />
        </template>
      </FormItemWrapper>
      <Card class="flex flex-col gap-4 bg-accent p-4 col-span-2">
        <FormItemWrapper name="contact_on_behalf" type="checkbox" :unchecked-value="false" :checked-value="true">
          <template #default="{ slots }">
            <div>
              <div class="flex items-center gap-2">
                <Checkbox id="contact_on_behalf" :model-value="slots.value" v-bind="slots.componentField" />
                <Label for="contact_on_behalf">Include me in the email chain</Label>
              </div>
            </div>
          </template>
        </FormItemWrapper>
        <p class="text-sm text-accent-foreground">We will send you a copy of the introductory email</p>
      </Card>
      <div class="col-span-2 flex justify-center">
        <Button
          variant="default"
          class="h-10 px-8"
          :loading="isReferingContact"
          :disabled="isReferingContact"
          type="submit"
          >Invite</Button
        >
      </div>
    </form>
  </div>
</template>

<script setup lang="ts">
import * as z from 'zod';
import { useForm } from 'vee-validate';
import { toTypedSchema } from '@vee-validate/zod';
import { userNameRegex } from '~/constants/regularExpressions';
import { computed } from 'vue';
import { referContact, type ReferForm, type ReferContactResponse } from '~/client';

interface Emit {
  (e: 'success'): void;
}

const emits = defineEmits<Emit>();

const useReferContact = defineMutation(() => {
  const { mutate: callReferContact, asyncStatus } = useMutation({
    mutation: async (referForm: ReferForm) =>
      (await referContact({
        composable: '$fetch',
        body: referForm,
      })) as ReferContactResponse,
    onSuccess() {
      showToastSuccess('Contact referred successfully');
      emits('success');
    },
    onError(error) {
      showToastError(error);
    },
  });

  return {
    callReferContact,
    isReferingContact: computed(() => asyncStatus.value === 'loading'),
  };
});

const { callReferContact, isReferingContact } = useReferContact();

const formSchema = toTypedSchema(
  z.object({
    first_name: z
      .string({ message: 'First Name is required' })
      .trim()
      .min(1, { message: 'First Name is required' })
      .max(255, { message: 'First name cannot exceed 255 characters' })
      .regex(userNameRegex, {
        message: 'Name can only contain letters, numbers, spaces, hyphens, apostrophes, and periods',
      }),

    last_name: z
      .string({ message: 'Last Name is required' })
      .trim()
      .min(1, { message: 'Last Name is required' })
      .max(255, { message: 'Last name cannot exceed 255 characters' })
      .regex(userNameRegex, {
        message: 'Name can only contain letters, numbers, spaces, hyphens, apostrophes, and periods',
      }),

    email: z
      .string({ message: 'Email is required' })
      .trim()
      .nonempty({ message: 'Email is required' })
      .email({ message: 'Please enter a valid email address' })
      .toLowerCase(),

    contact_on_behalf: z.boolean().default(false),
  })
);

const { handleSubmit } = useForm({
  validationSchema: formSchema,
});

const onSubmit = handleSubmit((referForm) => {
  callReferContact(referForm);
});
</script>

<style scoped lang="scss"></style>
